"""Freeze new source-verified diagnostic and untouched selection-holdout cases."""
import hashlib,json,shutil,sys,zipfile
from pathlib import Path
W=Path(__file__).resolve().parent;OUT=W/'v240-experiment'
REPO=Path(r'C:\Users\USRBGDY\.codex\worktrees\psb-retriever35-v8\adaptive-legal-rag')
if OUT.exists():raise ValueError('Frozen experiment already exists')
sys.path.insert(0,str(REPO/'focused-rag'))
from answer_guides import numbered_span
from token_budget import estimate_tokens
read=lambda p:json.loads(p.read_text(encoding='utf8'))
sha=lambda b:hashlib.sha256(b).hexdigest()
def write(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
with zipfile.ZipFile(W/'v230-comparison/knowledge-base.zip') as z:docs={n:z.read(n).decode('utf-8-sig') for n in z.namelist()}
cases=[]
def case(ident,question,golden,category,sources):
    support=[];oracle=[]
    for needle,clauses,starts in sources:
        matches=[n for n in docs if needle in n];assert len(matches)==1,needle
        name=matches[0];raw=docs[name]
        anchors=[]
        for prefix in starts:
            rows=[s for s in raw.splitlines() if s.startswith(prefix)]
            assert len(rows)==1,(ident,prefix,len(rows))
            anchors.append(rows[0])
        texts=[raw] if len(raw)<=14000 else [numbered_span(raw,c) for c in clauses]
        assert texts and all(t and t in raw for t in texts),(ident,name)
        assert all(any(a in t for t in texts) for a in anchors),(ident,name,'oracle misses anchor')
        support.append({'filename':name,'sha256':sha(raw.encode()),'anchors':anchors})
        for text in dict.fromkeys(texts):oracle.append({'filename':name,'sha256':sha(raw.encode()),'start':raw.index(text),'end':raw.index(text)+len(text),'text_sha256':sha(text.encode()),'full_document':text==raw})
    cases.append({'id':ident,'split':'development' if ident.startswith('D') else 'holdout','question':question,'golden':golden,'category':category,'support':support,'oracle':oracle})

